package shape

import (
"regexp"
"strings"

"github.com/KogenAI/kogen-verification/verify"
)

var spawnCall = regexp.MustCompile(`(?i)(spawn|exec|fork|system|shell|run|command|cmd)[[:alnum:]_]*[[:space:]]*[(]`)
var comparison = regexp.MustCompile(`assert|expect|===|==|[.]includes[(]|[.]match[(]|toContain|toMatch|toBe|toEqual|[.]test[(]`)

func stderrCompared(code string) bool {
for _, line := range strings.Split(code, string(rune(10))) {
if strings.Contains(line, "stderr") && comparison.MatchString(line) {
return true
}
}
return false
}

func exitWrapperOf(body string) string {
code := stripJSComments(body)
if !spawnCall.MatchString(code) {
return ""
}
if stderrCompared(code) {
code += " status"
}
return verify.ExitWrapper(code)
}

func refineExitCodeItems(items []verify.StepItem, defs []verify.StepDef) []verify.StepItem {
var out []verify.StepItem
for _, it := range items {
if it.Check != "exit_code" {
out = append(out, it)
continue
}
start := len(out)
for _, d := range defs {
if d.File != it.Target {
continue
}
if w := exitWrapperOf(d.Body); w != "" {
out = append(out, verify.StepItem{Check: "exit_code", Target: it.Target, Detail: "step definition " + d.Pattern + " asserts an exit code but obtains it through " + w + ", which changes exit codes; build the binary (go build) and run it instead"})
}
}
if len(out) == start {
it.OK, it.Detail = true, ""
out = append(out, it)
}
}
return out
}

func stripJSComments(src string) string {
var b strings.Builder
var quote byte
star := string([]byte{42, 47})
for i := 0; i < len(src); i++ {
c := src[i]
switch {
case quote != 0:
b.WriteByte(c)
if c == 92 && i+1 < len(src) {
i++
b.WriteByte(src[i])
} else if c == quote {
quote = 0
}
case c == 39 || c == 34 || c == 96:
quote = c
b.WriteByte(c)
case c == 47 && i+1 < len(src) && src[i+1] == 47:
for i < len(src) && src[i] != 10 {
i++
}
b.WriteByte(10)
case c == 47 && i+1 < len(src) && src[i+1] == 42:
end := strings.Index(src[i+2:], star)
if end < 0 {
i = len(src)
} else {
i += end + 3
}
b.WriteByte(32)
default:
b.WriteByte(c)
}
}
return b.String()
}

